@charset "UTF-8";
html {
  -ms-text-size-adjust: 100%;
  -webkit-text-size-adjust: 100%;
  -ms-overflow-style: -ms-autohiding-scrollbar;
  box-sizing: border-box;
}
abbr,
blockquote,
body,
button,
dd,
dl,
dt,
fieldset,
figure,
form,
h1,
h2,
h3,
h4,
h5,
h6,
hgroup,
input,
legend,
li,
ol,
p,
pre,
ul {
  margin: 0;
  padding: 0;
}
address,
caption,
code,
figcaption,
pre,
th {
  font-size: 1em;
  font-style: normal;
  font-weight: 400;
}
fieldset,
iframe {
  border: 0;
}
caption,
th {
  text-align: start;
}
table {
  border-collapse: collapse;
  border-spacing: 0;
}
audio,
canvas,
progress,
video {
  vertical-align: baseline;
}
button {
  background: none;
  border: 0;
  color: inherit;
  cursor: pointer;
  font: inherit;
  line-height: inherit;
  vertical-align: inherit;
}
button:disabled {
  cursor: default;
}
::-moz-focus-inner {
  border: 0;
  padding: 0;
}
*,
:after,
:before {
  box-sizing: inherit;
}
a,
blockquote,
body,
code,
dd,
div,
